import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';

const routes: Routes = [
  { path: '', redirectTo: 'bundlemanagement', pathMatch: 'full' },
  { path: 'bundlemanagement/:id', loadComponent: () => import('../../components/bundlemanagement/bundlemanagement/bundlemanagement.component').then(m => m.BundlemanagementComponent) },
]

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class BundlemanagementRoutingModule { }
